# 足链闭合面与珠粒归同一件；踝后半环被小腿自然遮挡的补全放在组中仍可编辑。
def chain(pid,pts,pendants):
 # 采用由折线两侧生成的窄闭合面，不使用描线。
 import math
 path=[]
 for P in pts:
  a=[];b=[]
  for i,(x,y) in enumerate(P):
   prev=P[max(i-1,0)];nxt=P[min(i+1,len(P)-1)];dx=nxt[0]-prev[0];dy=nxt[1]-prev[1];L=math.hypot(dx,dy) or 1;nx=-dy/L*.6;ny=dx/L*.6;a.append((x+nx,y+ny));b.append((x-nx,y-ny))
  path.append('M '+' L '.join(f'{x:.2f},{y:.2f}' for x,y in a+b[::-1])+' Z')
 more=''.join(circ(x,y,1.8) for P in pts for x,y in P)
 for x,y in pendants:
  path.append(f'M {x},{y-5} C {x-4},{y-1} {x-5},{y+2} {x},{y+7} C {x+5},{y+2} {x+4},{y-1} {x},{y-5} Z')
 if pid=='foot_chain_right': path.append('M 410.4,1526.5 C 410.4,1540 410.1,1552.5 408.4,1563 L 409.4,1569.5 L 410.6,1569.3 L 409.6,1563 C 411.3,1552.7 411.6,1540 411.6,1526.5 Z')
 if pid=='foot_chain_left': path.append('M 478.4,1525.5 L 478.4,1569.5 L 479.6,1569.5 L 479.6,1525.5 Z')
 add(pid,' '.join(path),more=more)
